Definition cred (A : astate) (sc c : Z) : Prop :=
  c = 0 \/
  (0 < c /\ exists g mt aib sl, a_active A sc = [g] /\ a_meta A g = Some mt /\ mt_role mt = RGroup aib sl /\ c <= count_idle sl).

